// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address proxyCaller, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(proxyCaller != address(0));

        Forwarder f = new Forwarder();

        vm.deal(proxyCaller, amount);

        vm.prank(proxyCaller);
        f.forwardWithValue{value: amount}(address(c));

        assertTrue(c.getBalance(address(f)) == amount);
    }
}

contract Forwarder {
    receive() external payable {}
    function forwardWithValue(address target) external payable {
        (bool s, ) = target.call{value: msg.value}(abi.encodeWithSignature("addToBalance()"));
        require(s);
    }
}
